/* ============================================================================
   OG-BASE — the Sample 2 loader screen, as a guest first sees it.

   A real capture of the invitation's opening moment (1200x630): the dark
   doors, the maroon wax seal with its radial sheen and dashed gold rim,
   the mandala rings, the breathing halo, "TAP THE SEAL TO OPEN". The demo
   monogram is removed from the seal; the og renderer paints the couple's
   own two initials in its place, exactly where the site puts them — so
   the WhatsApp card IS the website's first screen, per couple.
   Embedded as a base64 PNG (~292 KB) — one asset, zero fetches on the edge.
   ========================================================================= */
"use strict";
const zlib = require("zlib");
const B64 = "";
let CACHE = null;
/** Decode the base PNG once per isolate. Returns a Buffer of RGB triples. */
function baseImage() {
  if (CACHE) return CACHE;
  const png = Buffer.from(B64, "base64");
  CACHE = decodePngToRgb(png);
  return CACHE;
}
/* Minimal PNG reader for one IDAT, 8-bit truecolour, no interlace — exactly
   what the writer above produces. Filters 0-4 are supported so the asset
   can be re-optimised later without breaking this. */
function decodePngToRgb(png) {
  let off = 8;
  let w = 0, h = 0, bitDepth = 8, colorType = 2;
  const idat = [];
  while (off < png.length) {
    const len = png.readUInt32BE(off);
    const type = png.toString("ascii", off + 4, off + 8);
    const data = png.subarray(off + 8, off + 8 + len);
    if (type === "IHDR") {
      w = data.readUInt32BE(0); h = data.readUInt32BE(4);
      bitDepth = data[8]; colorType = data[9];
    } else if (type === "IDAT") idat.push(data);
    else if (type === "IEND") break;
    off += 12 + len;
  }
  if (bitDepth !== 8 || colorType !== 2) throw new Error("UNSUPPORTED_PNG");
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const stride = w * 3;
  const out = Buffer.alloc(w * h * 3);
  const line = Buffer.alloc(stride);
  const prev = Buffer.alloc(stride);
  let p = 0;
  for (let y = 0; y < h; y++) {
    const filter = raw[p++];
    raw.copy(line, 0, p, p + stride);
    p += stride;
    if (filter === 1) for (let i = 3; i < stride; i++) line[i] = (line[i] + line[i - 3]) & 255;
    else if (filter === 2) for (let i = 0; i < stride; i++) line[i] = (line[i] + prev[i]) & 255;
    else if (filter === 3) for (let i = 0; i < stride; i++) {
      const left = i >= 3 ? line[i - 3] : 0;
      line[i] = (line[i] + ((left + prev[i]) >> 1)) & 255;
    } else if (filter === 4) for (let i = 0; i < stride; i++) {
      const a = i >= 3 ? line[i - 3] : 0;
      const b = prev[i];
      const c = i >= 3 ? prev[i - 3] : 0;
      const pa = Math.abs(b - c), pb = Math.abs(a - c), pc = Math.abs(a + b - 2 * c);
      const pred = (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
      line[i] = (line[i] + pred) & 255;
    }
    line.copy(out, y * stride);
    line.copy(prev, 0);
  }
  return { rgb: out, w, h };
}
module.exports = { baseImage };
